<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Global Aid Alliance — Together We Respond</title>
<meta name="description" content="A humanitarian nonprofit organization dedicated to disaster relief, emergency assistance, and community resilience worldwide.">
<style>
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
:root{
  --red:#C41E3A;
  --red-dark:#a01830;
  --navy:#1B3A5C;
  --navy-light:#264d73;
  --white:#FFFFFF;
  --gray-50:#F9FAFB;
  --gray-100:#F3F4F6;
  --gray-200:#E5E7EB;
  --gray-300:#D1D5DB;
  --gray-500:#6B7280;
  --gray-600:#4B5563;
  --gray-700:#374151;
  --gray-800:#1F2937;
  --gray-900:#111827;
  --font-heading:'Segoe UI',Roboto,'Helvetica Neue',Arial,sans-serif;
  --font-body:'Segoe UI',Roboto,'Helvetica Neue',Arial,sans-serif;
  --max-w:1200px;
  --section-py:5rem;
}
html{scroll-behavior:smooth;font-size:16px}
body{font-family:var(--font-body);color:var(--gray-800);line-height:1.6;background:var(--white)}
img{max-width:100%;display:block}
a{color:inherit;text-decoration:none}
button{cursor:pointer;font-family:inherit}
ul{list-style:none}
h1,h2,h3,h4{font-family:var(--font-heading);line-height:1.2}

.container{max-width:var(--max-w);margin:0 auto;padding:0 1.5rem}
.btn{display:inline-block;padding:.75rem 1.75rem;border-radius:.375rem;font-weight:600;font-size:1rem;border:none;transition:all .2s ease}
.btn-primary{background:var(--red);color:var(--white)}
.btn-primary:hover{background:var(--red-dark)}
.btn-secondary{background:transparent;color:var(--white);border:2px solid var(--white)}
.btn-secondary:hover{background:rgba(255,255,255,.15)}
.btn-navy{background:var(--navy);color:var(--white)}
.btn-navy:hover{background:var(--navy-light)}
.btn-outline{background:transparent;color:var(--red);border:2px solid var(--red)}
.btn-outline:hover{background:var(--red);color:var(--white)}
.section-label{text-transform:uppercase;font-size:.85rem;letter-spacing:.1em;color:var(--red);font-weight:700;margin-bottom:.5rem}
.section-title{font-size:2.25rem;color:var(--gray-900);margin-bottom:1rem}
.section-subtitle{font-size:1.1rem;color:var(--gray-600);max-width:640px}

/* ── HEADER ── */
.utility-bar{background:var(--gray-900);color:var(--gray-300);font-size:.8rem;padding:.4rem 0}
.utility-bar .container{display:flex;justify-content:flex-end;gap:1.25rem}
.utility-bar a{color:var(--gray-300);transition:color .2s}
.utility-bar a:hover{color:var(--white)}

.main-header{background:var(--white);border-bottom:1px solid var(--gray-200);position:sticky;top:0;z-index:100;box-shadow:0 1px 3px rgba(0,0,0,.06)}
.main-header .container{display:flex;align-items:center;justify-content:space-between;padding-top:.75rem;padding-bottom:.75rem}
.logo{display:flex;align-items:center;gap:.6rem;font-weight:800;font-size:1.25rem;color:var(--red)}
.logo svg{flex-shrink:0}
.nav-links{display:flex;align-items:center;gap:1.5rem;font-size:.95rem;font-weight:500}
.nav-links a{color:var(--gray-700);transition:color .2s}
.nav-links a:hover{color:var(--red)}
.nav-links .btn{font-size:.9rem;padding:.55rem 1.25rem}
.hamburger{display:none;background:none;border:none;padding:.25rem}
.hamburger svg{width:28px;height:28px;color:var(--gray-700)}

/* Mobile nav */
.mobile-nav{position:fixed;top:0;right:0;bottom:0;width:280px;background:var(--white);z-index:200;transform:translateX(100%);transition:transform .3s ease;box-shadow:-4px 0 20px rgba(0,0,0,.15);padding:1.5rem}
.mobile-nav.open{transform:translateX(0)}
.mobile-overlay{position:fixed;inset:0;background:rgba(0,0,0,.4);z-index:199;opacity:0;pointer-events:none;transition:opacity .3s}
.mobile-overlay.open{opacity:1;pointer-events:auto}
.mobile-nav-close{background:none;border:none;float:right;margin-bottom:1rem}
.mobile-nav-close svg{width:24px;height:24px;color:var(--gray-700)}
.mobile-nav ul{clear:both;display:flex;flex-direction:column;gap:.25rem}
.mobile-nav ul li a{display:block;padding:.75rem .5rem;font-size:1.05rem;color:var(--gray-700);border-radius:.375rem;transition:background .2s}
.mobile-nav ul li a:hover{background:var(--gray-100)}
.mobile-nav .btn{display:block;text-align:center;margin-top:1rem}

/* ── HERO ── */
.hero{background:linear-gradient(135deg,var(--navy) 0%,#0f2440 100%);color:var(--white);padding:6rem 0 5rem;position:relative;overflow:hidden}
.hero::before{content:'';position:absolute;inset:0;background:url("data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' fill-rule='evenodd'%3E%3Cg fill='%23ffffff' fill-opacity='0.03'%3E%3Cpath d='M36 34v-4h-2v4h-4v2h4v4h2v-4h4v-2h-4zm0-30V0h-2v4h-4v2h4v4h2V6h4V4h-4zM6 34v-4H4v4H0v2h4v4h2v-4h4v-2H6zM6 4V0H4v4H0v2h4v4h2V6h4V4H6z'/%3E%3C/g%3E%3C/g%3E%3C/svg%3E") repeat}
.hero .container{position:relative;z-index:1;max-width:800px}
.hero h1{font-size:3.25rem;font-weight:800;margin-bottom:1.25rem;line-height:1.1}
.hero p{font-size:1.2rem;color:rgba(255,255,255,.85);margin-bottom:2.25rem;line-height:1.7}
.hero-ctas{display:flex;gap:1rem;flex-wrap:wrap}
.hero-ctas .btn{font-size:1.05rem;padding:.85rem 2rem}

/* ── MISSION ── */
.mission{padding:var(--section-py) 0;background:var(--white)}
.mission .container{max-width:860px;text-align:center}
.mission h2{margin-bottom:1.5rem}
.mission p{color:var(--gray-600);font-size:1.05rem;line-height:1.8}
.mission p+p{margin-top:1rem}

/* ── IMPACT STATS ── */
.impact{padding:var(--section-py) 0;background:var(--red);color:var(--white)}
.impact .container{text-align:center}
.impact h2{color:var(--white);margin-bottom:.5rem}
.impact .section-label{color:rgba(255,255,255,.7)}
.impact-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:2rem;margin-top:3rem}
.stat-card{text-align:center}
.stat-number{font-size:3rem;font-weight:800;line-height:1;margin-bottom:.4rem}
.stat-label{font-size:1rem;opacity:.85;font-weight:500}
.impact-note{margin-top:2.5rem;font-size:1rem;opacity:.8;max-width:640px;margin-left:auto;margin-right:auto}

/* ── PROGRAMS ── */
.programs{padding:var(--section-py) 0;background:var(--gray-50)}
.accordion{margin-top:2.5rem;max-width:800px}
.accordion-item{background:var(--white);border:1px solid var(--gray-200);border-radius:.5rem;margin-bottom:.75rem;overflow:hidden}
.accordion-header{width:100%;display:flex;align-items:center;justify-content:space-between;padding:1.15rem 1.5rem;background:none;border:none;font-size:1.1rem;font-weight:600;color:var(--gray-900);text-align:left;transition:background .2s}
.accordion-header:hover{background:var(--gray-50)}
.accordion-header svg{width:20px;height:20px;color:var(--gray-500);transition:transform .3s;flex-shrink:0}
.accordion-item.active .accordion-header svg{transform:rotate(180deg)}
.accordion-body{max-height:0;overflow:hidden;transition:max-height .35s ease}
.accordion-body-inner{padding:0 1.5rem 1.25rem;color:var(--gray-600);line-height:1.7;font-size:.98rem}

/* ── GET INVOLVED ── */
.get-involved{padding:var(--section-py) 0;background:var(--white)}
.involve-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:2rem;margin-top:2.5rem}
.involve-card{border:1px solid var(--gray-200);border-radius:.75rem;padding:2rem;text-align:center;transition:box-shadow .2s}
.involve-card:hover{box-shadow:0 4px 20px rgba(0,0,0,.08)}
.involve-icon{width:56px;height:56px;background:var(--red);border-radius:50%;display:flex;align-items:center;justify-content:center;margin:0 auto 1.25rem}
.involve-icon svg{width:26px;height:26px;color:var(--white)}
.involve-card h3{font-size:1.2rem;margin-bottom:.75rem;color:var(--gray-900)}
.involve-card p{font-size:.95rem;color:var(--gray-600);margin-bottom:1.25rem;line-height:1.6}

/* ── NEWS CAROUSEL ── */
.news{padding:var(--section-py) 0;background:var(--gray-50)}
.carousel-wrapper{position:relative;margin-top:2.5rem;overflow:hidden}
.carousel-track{display:flex;transition:transform .4s ease}
.news-card{min-width:calc(33.333% - 1.333rem);margin-right:2rem;background:var(--white);border-radius:.75rem;border:1px solid var(--gray-200);overflow:hidden;flex-shrink:0}
.news-card-img{height:180px;background:var(--gray-200);display:flex;align-items:center;justify-content:center;color:var(--gray-400);font-size:.85rem}
.news-card-body{padding:1.5rem}
.news-card-body h3{font-size:1.1rem;margin-bottom:.5rem;color:var(--gray-900)}
.news-card-body p{font-size:.93rem;color:var(--gray-600);line-height:1.6}
.news-card-body .read-more{display:inline-block;margin-top:.75rem;color:var(--red);font-weight:600;font-size:.9rem}
.news-card-body .read-more:hover{text-decoration:underline}
.carousel-controls{display:flex;gap:.75rem;margin-top:1.75rem;justify-content:center}
.carousel-btn{width:44px;height:44px;border-radius:50%;border:2px solid var(--gray-300);background:var(--white);display:flex;align-items:center;justify-content:center;transition:all .2s}
.carousel-btn:hover{border-color:var(--red);color:var(--red)}
.carousel-btn svg{width:18px;height:18px}

/* ── DONATE CTA ── */
.donate-cta{padding:var(--section-py) 0;background:linear-gradient(135deg,var(--navy) 0%,#0f2440 100%);color:var(--white);text-align:center}
.donate-cta h2{color:var(--white);font-size:2.25rem;margin-bottom:1rem}
.donate-cta p{color:rgba(255,255,255,.8);font-size:1.1rem;max-width:600px;margin:0 auto 2.5rem;line-height:1.7}
.donate-cta .btn{font-size:1.1rem;padding:.9rem 2.5rem}

/* ── FOOTER ── */
.footer{background:var(--gray-900);color:var(--gray-300);padding:3.5rem 0 0}
.footer-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:2.5rem}
.footer-col h4{color:var(--white);font-size:1rem;margin-bottom:1rem;font-weight:700}
.footer-col a{display:block;padding:.25rem 0;font-size:.9rem;color:var(--gray-400);transition:color .2s}
.footer-col a:hover{color:var(--white)}
.footer-bottom{margin-top:3rem;padding:1.5rem 0;border-top:1px solid rgba(255,255,255,.1);display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:1rem}
.footer-bottom p{font-size:.85rem;color:var(--gray-500)}
.social-links{display:flex;gap:1rem}
.social-links a{width:36px;height:36px;border-radius:50%;background:rgba(255,255,255,.08);display:flex;align-items:center;justify-content:center;transition:background .2s}
.social-links a:hover{background:var(--red)}
.social-links svg{width:16px;height:16px;color:var(--gray-300)}

/* ── DONATE MODAL ── */
.modal-overlay{position:fixed;inset:0;background:rgba(0,0,0,.5);z-index:300;opacity:0;pointer-events:none;transition:opacity .3s;display:flex;align-items:center;justify-content:center}
.modal-overlay.open{opacity:1;pointer-events:auto}
.modal{background:var(--white);border-radius:1rem;max-width:520px;width:90%;max-height:90vh;overflow-y:auto;padding:2.5rem;position:relative;transform:translateY(20px);transition:transform .3s}
.modal-overlay.open .modal{transform:translateY(0)}
.modal-close{position:absolute;top:1rem;right:1rem;background:none;border:none;padding:.25rem}
.modal-close svg{width:24px;height:24px;color:var(--gray-500)}
.modal h2{font-size:1.5rem;color:var(--gray-900);margin-bottom:.5rem}
.modal>p{color:var(--gray-600);font-size:.95rem;margin-bottom:1.75rem}
.amount-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:.75rem;margin-bottom:1.5rem}
.amount-option{padding:1rem;border:2px solid var(--gray-200);border-radius:.5rem;text-align:center;cursor:pointer;transition:all .2s;background:var(--white)}
.amount-option:hover,.amount-option.selected{border-color:var(--red);background:rgba(196,30,58,.04)}
.amount-option .amount{font-size:1.35rem;font-weight:700;color:var(--gray-900);display:block}
.amount-option .impact-text{font-size:.82rem;color:var(--gray-500);margin-top:.25rem;display:block}
.custom-amount{margin-bottom:1.5rem}
.custom-amount label{display:block;font-weight:600;font-size:.9rem;color:var(--gray-700);margin-bottom:.4rem}
.custom-amount input{width:100%;padding:.7rem 1rem;border:2px solid var(--gray-200);border-radius:.375rem;font-size:1rem;transition:border-color .2s}
.custom-amount input:focus{outline:none;border-color:var(--red)}
.modal .btn{width:100%;text-align:center;padding:.85rem;font-size:1.1rem}

/* ── RESPONSIVE ── */
@media(max-width:1024px){
  .impact-grid{grid-template-columns:repeat(2,1fr)}
  .involve-grid{grid-template-columns:repeat(2,1fr)}
  .news-card{min-width:calc(50% - 1rem)}
}
@media(max-width:768px){
  :root{--section-py:3.5rem}
  .utility-bar{display:none}
  .nav-links{display:none}
  .hamburger{display:block}
  .hero{padding:4rem 0 3.5rem}
  .hero h1{font-size:2.25rem}
  .hero p{font-size:1.05rem}
  .section-title{font-size:1.75rem}
  .impact-grid{grid-template-columns:repeat(2,1fr);gap:1.5rem}
  .stat-number{font-size:2.25rem}
  .involve-grid{grid-template-columns:1fr}
  .news-card{min-width:calc(100% - 0rem);margin-right:0}
  .carousel-track{flex-direction:column;gap:1rem;transform:none !important}
  .footer-grid{grid-template-columns:repeat(2,1fr)}
  .footer-bottom{flex-direction:column;text-align:center}
}
@media(max-width:480px){
  .hero h1{font-size:1.85rem}
  .hero-ctas{flex-direction:column}
  .hero-ctas .btn{text-align:center}
  .impact-grid{grid-template-columns:1fr}
  .amount-grid{grid-template-columns:1fr}
  .footer-grid{grid-template-columns:1fr}
}
</style>
</head>
<body>

<!-- Utility Bar -->
<div class="utility-bar">
  <div class="container">
    <a href="#signin">Sign In</a>
    <a href="#contact">Contact Us</a>
    <a href="#espanol">Espa&ntilde;ol</a>
  </div>
</div>

<!-- Main Header -->
<header class="main-header">
  <div class="container">
    <a href="#" class="logo">
      <svg width="36" height="36" viewBox="0 0 36 36" fill="none">
        <circle cx="18" cy="18" r="18" fill="#C41E3A"/>
        <path d="M18 8v20M8 18h20" stroke="#fff" stroke-width="3.5" stroke-linecap="round"/>
      </svg>
      Global Aid Alliance
    </a>
    <nav class="nav-links" aria-label="Main navigation">
      <a href="#mission">About Us</a>
      <a href="#programs">Disaster Relief</a>
      <a href="#programs">Programs &amp; Services</a>
      <a href="#get-involved">Volunteer</a>
      <a href="#footer">Find Local Chapter</a>
      <a href="#" class="btn btn-primary" id="headerDonateBtn">Donate</a>
    </nav>
    <button class="hamburger" id="hamburgerBtn" aria-label="Open navigation menu">
      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><line x1="3" y1="6" x2="21" y2="6"/><line x1="3" y1="12" x2="21" y2="12"/><line x1="3" y1="18" x2="21" y2="18"/></svg>
    </button>
  </div>
</header>

<!-- Mobile Navigation -->
<div class="mobile-overlay" id="mobileOverlay"></div>
<nav class="mobile-nav" id="mobileNav" aria-label="Mobile navigation">
  <button class="mobile-nav-close" id="mobileNavClose" aria-label="Close navigation menu">
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
  </button>
  <ul>
    <li><a href="#mission" class="mobile-nav-link">About Us</a></li>
    <li><a href="#programs" class="mobile-nav-link">Disaster Relief</a></li>
    <li><a href="#programs" class="mobile-nav-link">Programs &amp; Services</a></li>
    <li><a href="#get-involved" class="mobile-nav-link">Volunteer</a></li>
    <li><a href="#footer" class="mobile-nav-link">Find Local Chapter</a></li>
  </ul>
  <a href="#" class="btn btn-primary mobile-donate-btn">Donate</a>
</nav>

<!-- Hero -->
<section class="hero" id="hero">
  <div class="container">
    <h1>When Disaster Strikes, We're There</h1>
    <p>From hurricanes and wildfires to global health emergencies, Global Aid Alliance delivers immediate relief and long-term recovery support to communities in crisis.</p>
    <div class="hero-ctas">
      <a href="#" class="btn btn-primary" id="heroDonateBtn">Donate Now</a>
      <a href="#get-involved" class="btn btn-secondary">Become a Volunteer</a>
    </div>
  </div>
</section>

<!-- Mission -->
<section class="mission" id="mission">
  <div class="container">
    <span class="section-label">Our Mission</span>
    <h2 class="section-title">Preventing &amp; Alleviating Human Suffering</h2>
    <p>Global Aid Alliance prevents and alleviates human suffering in the face of emergencies by mobilizing the power of volunteers and the generosity of donors.</p>
    <p>We are guided by the fundamental principles of humanity, impartiality, and neutrality. Every day, our teams work across borders and boundaries to ensure that help reaches those who need it most&nbsp;&mdash; regardless of race, religion, nationality, or political affiliation. From the first hours of a disaster to the years of recovery that follow, we stand with affected communities every step of the way.</p>
  </div>
</section>

<!-- Impact Stats -->
<section class="impact" id="impact-stats">
  <div class="container">
    <span class="section-label">Our Impact</span>
    <h2 class="section-title" style="color:#fff">Making a Difference Worldwide</h2>
    <div class="impact-grid">
      <div class="stat-card">
        <div class="stat-number" data-target="12000000" data-prefix="" data-suffix="">12M</div>
        <div class="stat-label">People Assisted Annually</div>
      </div>
      <div class="stat-card">
        <div class="stat-number" data-target="50000" data-prefix="" data-suffix="">50,000</div>
        <div class="stat-label">Active Volunteers</div>
      </div>
      <div class="stat-card">
        <div class="stat-number" data-target="190" data-prefix="" data-suffix="">190</div>
        <div class="stat-label">Countries Served</div>
      </div>
      <div class="stat-card">
        <div class="stat-number" data-target="850" data-prefix="$" data-suffix="M">$850M</div>
        <div class="stat-label">Raised Last Fiscal Year</div>
      </div>
    </div>
    <p class="impact-note">These figures represent real lives changed&nbsp;&mdash; families sheltered after storms, blood delivered to hospitals, and communities rebuilt stronger than before.</p>
  </div>
</section>

<!-- Programs -->
<section class="programs" id="programs">
  <div class="container">
    <span class="section-label">What We Do</span>
    <h2 class="section-title">Programs &amp; Services</h2>
    <p class="section-subtitle">From immediate disaster response to long-term community health, our programs address the full spectrum of humanitarian need.</p>
    <div class="accordion">
      <div class="accordion-item active">
        <button class="accordion-header" aria-expanded="true">
          Disaster Relief
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><polyline points="6 9 12 15 18 9"/></svg>
        </button>
        <div class="accordion-body" style="max-height:200px">
          <div class="accordion-body-inner">Rapid deployment of emergency shelter, food, water, and medical supplies to communities affected by natural disasters and conflict. Our response teams are on the ground within 24 hours.</div>
        </div>
      </div>
      <div class="accordion-item">
        <button class="accordion-header" aria-expanded="false">
          Blood Donation
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><polyline points="6 9 12 15 18 9"/></svg>
        </button>
        <div class="accordion-body">
          <div class="accordion-body-inner">Operating one of the largest blood collection networks, we supply approximately 40% of the nation's blood and blood products to hospitals and medical facilities.</div>
        </div>
      </div>
      <div class="accordion-item">
        <button class="accordion-header" aria-expanded="false">
          Emergency Preparedness
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><polyline points="6 9 12 15 18 9"/></svg>
        </button>
        <div class="accordion-body">
          <div class="accordion-body-inner">Training individuals, families, and organizations to prepare for and respond to emergencies through workshops, certification courses, and community drills.</div>
        </div>
      </div>
      <div class="accordion-item">
        <button class="accordion-header" aria-expanded="false">
          International Humanitarian Aid
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><polyline points="6 9 12 15 18 9"/></svg>
        </button>
        <div class="accordion-body">
          <div class="accordion-body-inner">Partnering with a global network of humanitarian organizations to deliver relief and recovery programs in conflict zones and disaster-affected regions worldwide.</div>
        </div>
      </div>
      <div class="accordion-item">
        <button class="accordion-header" aria-expanded="false">
          Community Health
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><polyline points="6 9 12 15 18 9"/></svg>
        </button>
        <div class="accordion-body">
          <div class="accordion-body-inner">Providing health and safety education, disease prevention programs, and support services to underserved communities, including mental health resources for disaster survivors.</div>
        </div>
      </div>
    </div>
  </div>
</section>

<!-- Get Involved -->
