<script>
(function(){
  // ── Mobile Menu ──
  const hamburger = document.getElementById('hamburgerBtn');
  const mobileNav = document.getElementById('mobileNav');
  const mobileOverlay = document.getElementById('mobileOverlay');
  const mobileClose = document.getElementById('mobileNavClose');

  function openMobile(){mobileNav.classList.add('open');mobileOverlay.classList.add('open');document.body.style.overflow='hidden'}
  function closeMobile(){mobileNav.classList.remove('open');mobileOverlay.classList.remove('open');document.body.style.overflow=''}

  hamburger.addEventListener('click',openMobile);
  mobileClose.addEventListener('click',closeMobile);
  mobileOverlay.addEventListener('click',closeMobile);
  document.querySelectorAll('.mobile-nav-link').forEach(function(l){l.addEventListener('click',closeMobile)});

  // ── Donate Modal ──
  const modal = document.getElementById('donateModal');
  const modalCloseBtn = document.getElementById('modalClose');

  function openModal(e){if(e)e.preventDefault();modal.classList.add('open');document.body.style.overflow='hidden'}
  function closeModal(){modal.classList.remove('open');document.body.style.overflow=''}

  document.getElementById('heroDonateBtn').addEventListener('click',openModal);
  document.getElementById('headerDonateBtn').addEventListener('click',openModal);
  document.getElementById('ctaDonateBtn').addEventListener('click',openModal);
  document.querySelector('.mobile-donate-btn').addEventListener('click',function(e){closeMobile();openModal(e)});
  document.querySelectorAll('.footer-donate-link').forEach(function(l){l.addEventListener('click',openModal)});
  modalCloseBtn.addEventListener('click',closeModal);
  modal.addEventListener('click',function(e){if(e.target===modal)closeModal()});
  document.addEventListener('keydown',function(e){if(e.key==='Escape')closeModal()});

  // Amount selection
  var amountOptions = document.querySelectorAll('.amount-option');
  var customInput = document.getElementById('customAmount');
  amountOptions.forEach(function(opt){
    opt.addEventListener('click',function(){
      amountOptions.forEach(function(o){o.classList.remove('selected')});
      opt.classList.add('selected');
      customInput.value='';
    });
  });
  customInput.addEventListener('focus',function(){
    amountOptions.forEach(function(o){o.classList.remove('selected')});
  });

  document.getElementById('donateSubmit').addEventListener('click',function(){
    var selected = document.querySelector('.amount-option.selected');
    var amount = customInput.value || (selected ? selected.dataset.amount : '');
    if(amount){
      alert('Thank you for your generous donation of $'+amount+'! In a production environment, this would proceed to a secure payment processor.');
      closeModal();
    }
  });

  // ── Accordion ──
  document.querySelectorAll('.accordion-header').forEach(function(header){
    header.addEventListener('click',function(){
      var item = header.parentElement;
      var body = item.querySelector('.accordion-body');
      var inner = body.querySelector('.accordion-body-inner');
      var isActive = item.classList.contains('active');

      document.querySelectorAll('.accordion-item').forEach(function(ai){
        ai.classList.remove('active');
        ai.querySelector('.accordion-header').setAttribute('aria-expanded','false');
        ai.querySelector('.accordion-body').style.maxHeight='0';
      });

      if(!isActive){
        item.classList.add('active');
        header.setAttribute('aria-expanded','true');
        body.style.maxHeight=inner.scrollHeight+'px';
      }
    });
  });

  // ── News Carousel ──
  var track = document.getElementById('carouselTrack');
  var prevBtn = document.getElementById('carouselPrev');
  var nextBtn = document.getElementById('carouselNext');
  var currentSlide = 0;

  function getVisibleCount(){
    if(window.innerWidth<=768) return 0;
    if(window.innerWidth<=1024) return 2;
    return 3;
  }

  function updateCarousel(){
    var visible = getVisibleCount();
    if(visible===0){track.style.transform='';return}
    var cards = track.querySelectorAll('.news-card');
    var totalCards = cards.length;
    var maxSlide = Math.max(0, totalCards - visible);
    if(currentSlide>maxSlide) currentSlide=maxSlide;
    if(currentSlide<0) currentSlide=0;
    var cardWidth = cards[0].offsetWidth + 32;
    track.style.transform='translateX(-'+currentSlide*cardWidth+'px)';
  }

  prevBtn.addEventListener('click',function(){currentSlide--;updateCarousel()});
  nextBtn.addEventListener('click',function(){currentSlide++;updateCarousel()});
  window.addEventListener('resize',updateCarousel);

  // ── Animated Counters ──
  function animateCounters(){
    var stats = document.querySelectorAll('.stat-number');
    stats.forEach(function(stat){
      var target = parseInt(stat.dataset.target);
      var prefix = stat.dataset.prefix||'';
      var suffix = stat.dataset.suffix||'';
      var duration = 2000;
      var startTime = null;

      function formatNumber(n){
        if(target>=1000000) return prefix+(n/1000000).toFixed(n>=target?0:1)+'M'+suffix.replace('M','');
        if(target>=1000) return prefix+n.toLocaleString()+suffix;
        return prefix+n+suffix;
      }

      function step(timestamp){
        if(!startTime) startTime=timestamp;
        var progress=Math.min((timestamp-startTime)/duration,1);
        var eased=1-Math.pow(1-progress,3);
        var current=Math.floor(eased*target);
        if(target>=1000000){
          stat.textContent=prefix+(current/1000000).toFixed(progress<1?1:0)+'M';
        } else if(target>=1000){
          stat.textContent=prefix+current.toLocaleString()+suffix;
        } else {
          stat.textContent=prefix+current+suffix;
        }
        if(progress<1) requestAnimationFrame(step);
        else{
          if(target>=1000000) stat.textContent=prefix+'12M';
          else if(target===850) stat.textContent='$850M';
          else stat.textContent=prefix+target.toLocaleString()+suffix;
        }
      }
      requestAnimationFrame(step);
    });
  }

  var statsObserver = new IntersectionObserver(function(entries){
    entries.forEach(function(entry){
      if(entry.isIntersecting){
        animateCounters();
        statsObserver.disconnect();
      }
    });
  },{threshold:0.3});
  statsObserver.observe(document.getElementById('impact-stats'));
})();
</script>

